async function run(){await db.initialize();await rolesManager.initialize();const e=await db.models.user.findOne({where:{email:"superadmin@example.com"}});if(!e){console.error("Super Admin user not found in DB!");process.exit(1)}const r={getUser:()=>({id:e.id,role:String(e.roleId)}),metadata:{permission:"view.ecommerce.product"},headers:{}};console.log("Calling rolesGate directly...");await rolesGate(server,res,r,"/api/admin/ecommerce/product","GET",()=>{console.log("[rolesGate] Success! next() called.")});process.exit(0)}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db"),{rolesManager:rolesManager}=require("@b/utils/roles"),{rolesGate:rolesGate}=require("./src/handler/Middleware.js"),server={getRole:e=>rolesManager.roles.get(Number(e))},res={handleError(e,r){console.log(`[Mock Response] handleError called with status: ${e}, message: ${r}`)},sendResponse(e,r,s,o){console.log(`[Mock Response] sendResponse called with status: ${r}`)}};run();